//! Cargo-driven `d2d1.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", None),
        o => panic!("d2d1-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:dwrite", "import:xmllite", "import:ole32", "engine:wine", "engine:c:dxguid", "engine:c:dx10guid", "engine:uuid", "engine:oldnames", "engine:chkstk", "import:d3d10_1", "import:d3dcompiler_47", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:user32", "import:ucrtbase", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust", "engine:c:vcstartup", "engine:pseh"],
        "x86_64" => &["import:dwrite", "import:xmllite", "import:ole32", "engine:wine", "engine:c:dxguid", "engine:c:dx10guid", "engine:uuid", "engine:oldnames", "engine:chkstk", "import:d3d10_1", "import:d3dcompiler_47", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:user32", "import:ucrtbase", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust", "engine:c:vcstartup", "engine:pseh"],
        "aarch64" => &["import:dwrite", "import:xmllite", "import:ole32", "engine:wine", "engine:c:dxguid", "engine:c:dx10guid", "engine:uuid", "engine:oldnames", "engine:chkstk", "import:d3d10_1", "import:d3dcompiler_47", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:user32", "import:ucrtbase", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust", "engine:c:vcstartup", "engine:pseh"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/d2d1",
        "dll/directx/wine/d2d1",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/vkd3d/include",
        "vendor/vkd3d/include/private",
        "sdk/lib/pseh/include",
        "vendor/freetype/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x0600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_UNICODE",
        "_USE_MATH_DEFINES",
        "_WIN32_WINNT=0x0600",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("d2d1_shims", &["dll/directx/wine/d2d1/bitmap_render_target.c", "dll/directx/wine/d2d1/bitmap.c", "dll/directx/wine/d2d1/brush.c", "dll/directx/wine/d2d1/command_list.c", "dll/directx/wine/d2d1/dc_render_target.c", "dll/directx/wine/d2d1/device.c", "dll/directx/wine/d2d1/effect.c", "dll/directx/wine/d2d1/factory.c", "dll/directx/wine/d2d1/geometry.c", "dll/directx/wine/d2d1/hwnd_render_target.c", "dll/directx/wine/d2d1/layer.c", "dll/directx/wine/d2d1/mesh.c", "dll/directx/wine/d2d1/state_block.c", "dll/directx/wine/d2d1/stroke.c", "dll/directx/wine/d2d1/wic_render_target.c"])
        .rc("dll/directx/wine/d2d1/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/d2d1/d2d1.spec", "d2d1.dll")
        .spec_stubs()
        .delay_import_lib("dll/directx/wine/dwrite/dwrite.spec", "dwrite.dll", "dwrite")
        .delay_import_lib("dll/win32/xmllite/xmllite.spec", "xmllite.dll", "xmllite")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/directx/wine/d3d10_1/d3d10_1.spec", "d3d10_1.dll", "d3d10_1")
        .import_lib("dll/directx/wine/d3dcompiler_47/d3dcompiler_47.spec", "d3dcompiler_47.dll", "d3dcompiler_47")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/ucrtbase/ucrtbase.spec", "ucrtbase.dll", "ucrtbase")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
